--
-- Name: block_retired_asset_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_retired_asset_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status IN ('retired','disposed') AND NOT app_is_service_role() THEN
        RAISE EXCEPTION 'asset % is % and is read-only', OLD.asset_tag, OLD.status;
    END IF;
    RETURN NEW;
END $$;


--
-- Name: compute_next_due_at(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_next_due_at(p_template_id uuid, p_from timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE t maintenance_templates%ROWTYPE;
BEGIN
    SELECT * INTO t FROM maintenance_templates WHERE id = p_template_id;
    IF NOT FOUND OR NOT t.is_active OR t.trigger_type <> 'calendar' THEN
        RETURN NULL;   -- runtime/condition templates are evaluated by the scheduler
    END IF;
    RETURN p_from + make_interval(days => t.interval_days);
END $$;


--
-- Name: pick_template_for_asset(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pick_template_for_asset(p_asset_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
    SELECT mt.id
    FROM assets a
    JOIN maintenance_templates mt ON mt.category_id = a.category_id AND mt.is_active
    WHERE a.id = p_asset_id
    ORDER BY mt.created_at
    LIMIT 1
$$;


--
-- Name: reject_plain_password_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_plain_password_hash() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.password_hash IS NULL
       OR NEW.password_hash !~ '^(\$argon2(id|i|d)\$v=[0-9]+\$m=[0-9]+,t=[0-9]+,p=[0-9]+\$[A-Za-z0-9+/=]+\$[A-Za-z0-9+/=]+|\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53})$'
    THEN
        RAISE EXCEPTION 'users.password_hash must contain an Argon2 or bcrypt hash, never a plain password';
    END IF;
    RETURN NEW;
END $_$;


--
-- Name: seed_rand(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_rand(p_key text, p_max integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT (('x' || substr(md5(p_key), 1, 7))::bit(28)::integer) % p_max
$$;


