--
-- Name: asset_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asset_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    code text NOT NULL,
    name text NOT NULL,
    useful_life_months integer,
    requires_serial boolean DEFAULT false NOT NULL,
    default_specs jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asset_categories_code_shape CHECK ((code ~ '^[A-Z0-9_\-]{2,40}$'::text)),
    CONSTRAINT asset_categories_life_positive CHECK (((useful_life_months IS NULL) OR (useful_life_months > 0))),
    CONSTRAINT asset_categories_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT asset_categories_no_self_parent CHECK (((parent_id IS NULL) OR (parent_id <> id)))
);


--
-- Name: asset_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.asset_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
