    byte_size bigint NOT NULL,
    sha256_hex text NOT NULL,
    malware_scan_status public.malware_scan_status DEFAULT 'pending'::public.malware_scan_status NOT NULL,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asset_documents_amount_non_negative CHECK (((invoice_amount IS NULL) OR (invoice_amount >= (0)::numeric))),
    CONSTRAINT asset_documents_byte_size_positive CHECK ((byte_size > 0)),
    CONSTRAINT asset_documents_no_public_urls CHECK ((storage_key !~* '^(https?|s3|gs)://'::text)),
    CONSTRAINT asset_documents_sha256_shape CHECK ((sha256_hex ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT asset_documents_storage_not_blank CHECK (((btrim(storage_bucket) <> ''::text) AND (btrim(storage_key) <> ''::text)))
);


