--
-- Name: assets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    category_id uuid NOT NULL,
    current_location_id uuid NOT NULL,
    custodian_user_id uuid,
    asset_tag text NOT NULL,
    serial_number text,
    brand text,
    model text,
    specifications jsonb DEFAULT '{}'::jsonb NOT NULL,
    condition public.asset_condition DEFAULT 'unknown'::public.asset_condition NOT NULL,
    status public.asset_status DEFAULT 'draft'::public.asset_status NOT NULL,
    purchase_date date,
    purchase_cost numeric(14,2),
    next_maintenance_due_at timestamp with time zone,
    risk_band text DEFAULT 'unknown'::text NOT NULL,
    risk_reasons jsonb DEFAULT '[]'::jsonb NOT NULL,
    retired_at timestamp with time zone,
    retirement_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT assets_cost_non_negative CHECK (((purchase_cost IS NULL) OR (purchase_cost >= (0)::numeric))),
    CONSTRAINT assets_retired_fields CHECK ((((status <> ALL (ARRAY['retired'::public.asset_status, 'disposed'::public.asset_status])) AND (retired_at IS NULL)) OR ((status = ANY (ARRAY['retired'::public.asset_status, 'disposed'::public.asset_status])) AND (retired_at IS NOT NULL) AND (btrim(COALESCE(retirement_reason, ''::text)) <> ''::text)))),
    CONSTRAINT assets_risk_band_allowed CHECK ((risk_band = ANY (ARRAY['unknown'::text, 'low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT assets_risk_reasons_is_array CHECK ((jsonb_typeof(risk_reasons) = 'array'::text)),
    CONSTRAINT assets_serial_not_blank CHECK (((serial_number IS NULL) OR (btrim(serial_number) <> ''::text))),
    CONSTRAINT assets_tag_shape CHECK ((asset_tag ~ '^[A-Z0-9][A-Z0-9_\-]{2,63}$'::text))
);


