--
-- Name: dim_category; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dim_category AS
 SELECT c.id AS category_id,
    c.code AS category_code,
    c.name AS category_name,
    c.parent_id AS parent_category_id,
    COALESCE(p.code, c.code) AS category_group_code,
    COALESCE(p.name, c.name) AS category_group_name,
    c.useful_life_months,
    round(((c.useful_life_months)::numeric / 12.0), 1) AS useful_life_years,
    c.requires_serial
   FROM (public.asset_categories c
     LEFT JOIN public.asset_categories p ON ((p.id = c.parent_id)));


--
-- Name: dim_date; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dim_date AS
 SELECT (d)::date AS date_key,
    (EXTRACT(year FROM d))::integer AS year,
    (EXTRACT(quarter FROM d))::integer AS quarter,
    ('Q'::text || (EXTRACT(quarter FROM d))::integer) AS quarter_name,
    (EXTRACT(month FROM d))::integer AS month,
    to_char(d, 'Mon'::text) AS month_short,
    to_char(d, 'Month'::text) AS month_name,
    to_char(d, 'YYYY-MM'::text) AS year_month,
    (EXTRACT(day FROM d))::integer AS day_of_month,
    (EXTRACT(isodow FROM d))::integer AS day_of_week,
    to_char(d, 'Dy'::text) AS day_name,
    (EXTRACT(isodow FROM d) = ANY (ARRAY[(5)::numeric, (6)::numeric])) AS is_weekend,
    (date_trunc('month'::text, d))::date AS month_start,
    ((date_trunc('month'::text, d) + '1 mon -1 days'::interval))::date AS month_end
   FROM generate_series(('2019-01-01'::date)::timestamp with time zone, ('2029-12-31'::date)::timestamp with time zone, '1 day'::interval) d(d);


--
-- Name: org_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.org_units (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    name text NOT NULL,
    unit_type public.org_unit_type NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_units_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT org_units_no_self_parent CHECK (((parent_id IS NULL) OR (parent_id <> id)))
);


--
-- Name: dim_org_unit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dim_org_unit AS
 WITH RECURSIVE tree AS (
         SELECT o.id,
            o.parent_id,
            o.name,
            o.unit_type,
            o.is_active,
            o.name AS path,
            1 AS depth,
            o.name AS level_1,
            NULL::text AS level_2,
            NULL::text AS level_3,
            NULL::text AS level_4
           FROM public.org_units o
          WHERE (o.parent_id IS NULL)
        UNION ALL
         SELECT c.id,
            c.parent_id,
            c.name,
            c.unit_type,
            c.is_active,
            ((t.path || ' > '::text) || c.name),
            (t.depth + 1),
            t.level_1,
                CASE
                    WHEN ((t.depth + 1) = 2) THEN c.name
                    ELSE t.level_2
                END AS level_2,
                CASE
                    WHEN ((t.depth + 1) = 3) THEN c.name
                    ELSE t.level_3
                END AS level_3,
                CASE
                    WHEN ((t.depth + 1) = 4) THEN c.name
                    ELSE t.level_4
                END AS level_4
           FROM (public.org_units c
             JOIN tree t ON ((c.parent_id = t.id)))
        )
 SELECT id AS org_unit_id,
    parent_id AS parent_org_unit_id,
    name AS org_unit_name,
    (unit_type)::text AS org_unit_type,
    is_active,
    depth,
    path AS org_path,
    level_1 AS university,
    level_2 AS campus,
    level_3 AS college,
    level_4 AS department
   FROM tree;


--
-- Name: locations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.locations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    parent_id uuid,
    org_unit_id uuid NOT NULL,
    location_type public.location_type NOT NULL,
    name text NOT NULL,
    code text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT locations_code_not_blank CHECK (((code IS NULL) OR (btrim(code) <> ''::text))),
    CONSTRAINT locations_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT locations_no_self_parent CHECK (((parent_id IS NULL) OR (parent_id <> id)))
);


--
-- Name: dim_location; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dim_location AS
 WITH RECURSIVE tree AS (
         SELECT l.id,
            l.parent_id,
            l.org_unit_id,
            l.location_type,
            l.name,
            l.code,
            l.is_active,
            l.code AS path_code,
            l.name AS path_name,
            1 AS depth,
            l.name AS lvl1,
            NULL::text AS lvl2,
            NULL::text AS lvl3,
            NULL::text AS lvl4
           FROM public.locations l
          WHERE (l.parent_id IS NULL)
        UNION ALL
         SELECT c.id,
            c.parent_id,
            c.org_unit_id,
            c.location_type,
            c.name,
            c.code,
            c.is_active,
            ((t_1.path_code || '/'::text) || c.code),
            ((t_1.path_name || ' > '::text) || c.name),
            (t_1.depth + 1),
            t_1.lvl1,
                CASE
                    WHEN ((t_1.depth + 1) = 2) THEN c.name
                    ELSE t_1.lvl2
                END AS lvl2,
                CASE
                    WHEN ((t_1.depth + 1) = 3) THEN c.name
                    ELSE t_1.lvl3
                END AS lvl3,
                CASE
                    WHEN ((t_1.depth + 1) = 4) THEN c.name
                    ELSE t_1.lvl4
                END AS lvl4
           FROM (public.locations c
             JOIN tree t_1 ON ((c.parent_id = t_1.id)))
        )
 SELECT t.id AS location_id,
    t.parent_id AS parent_location_id,
    t.code AS location_code,
    t.name AS location_name,
    (t.location_type)::text AS location_type,
    t.is_active,
    t.depth,
    t.path_code AS location_path,
    t.path_name AS location_path_name,
    t.lvl1 AS campus,
    t.lvl2 AS building,
    t.lvl3 AS floor,
    t.lvl4 AS room,
    t.org_unit_id,
    o.org_unit_name,
    o.college,
    o.department
   FROM (tree t
     LEFT JOIN public.dim_org_unit o ON ((o.org_unit_id = t.org_unit_id)));


--
-- Name: roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    is_system boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT roles_code_shape CHECK ((code ~ '^[a-z][a-z0-9_]{2,63}$'::text)),
    CONSTRAINT roles_name_not_blank CHECK ((btrim(name) <> ''::text))
);


--
-- Name: user_roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_roles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    role_id uuid NOT NULL,
    org_unit_id uuid,
    granted_by uuid,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_roles_expiry_future CHECK (((expires_at IS NULL) OR (expires_at > created_at)))
);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email public.citext NOT NULL,
    full_name text NOT NULL,
    password_hash text NOT NULL,
    status public.user_status DEFAULT 'active'::public.user_status NOT NULL,
    mfa_enabled boolean DEFAULT false NOT NULL,
    last_login_at timestamp with time zone,
    failed_login_count integer DEFAULT 0 NOT NULL,
    locked_until timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT users_email_basic_shape CHECK (((email)::text ~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$'::text)),
    CONSTRAINT users_failed_login_non_negative CHECK ((failed_login_count >= 0)),
    CONSTRAINT users_full_name_not_blank CHECK ((btrim(full_name) <> ''::text)),
    CONSTRAINT users_password_hash_strong_shape CHECK ((password_hash ~ '^(\$argon2(id|i|d)\$v=[0-9]+\$m=[0-9]+,t=[0-9]+,p=[0-9]+\$[A-Za-z0-9+/=]+\$[A-Za-z0-9+/=]+|\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53})$'::text))
);


--
-- Name: TABLE users; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.users IS 'User identities. Plain passwords are never stored; password_hash must be Argon2id or bcrypt.';


--
-- Name: COLUMN users.password_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.password_hash IS 'One-way hash only, produced by the API layer.';


--
-- Name: dim_user; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.dim_user AS
 SELECT u.id AS user_id,
    u.full_name,
    (u.email)::text AS email,
    (u.status)::text AS user_status,
    u.mfa_enabled,
    u.last_login_at,
    (u.last_login_at)::date AS last_login_date,
    u.failed_login_count,
    ((u.locked_until IS NOT NULL) AND (u.locked_until > now())) AS is_locked,
    COALESCE(string_agg(DISTINCT r.name, ', '::text), 'No role'::text) AS roles,
    COALESCE(string_agg(DISTINCT o.name, ', '::text), 'University-wide'::text) AS role_scopes,
    count(DISTINCT ur.id) AS role_grant_count
   FROM (((public.users u
     LEFT JOIN public.user_roles ur ON (((ur.user_id = u.id) AND ((ur.expires_at IS NULL) OR (ur.expires_at > now())))))
     LEFT JOIN public.roles r ON ((r.id = ur.role_id)))
     LEFT JOIN public.org_units o ON ((o.id = ur.org_unit_id)))
  GROUP BY u.id, u.full_name, u.email, u.status, u.mfa_enabled, u.last_login_at, u.failed_login_count, u.locked_until;


--
-- Name: work_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.work_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asset_id uuid NOT NULL,
    template_id uuid,
    technician_user_id uuid,
    priority public.work_order_priority DEFAULT 'medium'::public.work_order_priority NOT NULL,
    status public.work_order_status DEFAULT 'open'::public.work_order_status NOT NULL,
    scheduled_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    checklist_result jsonb DEFAULT '{}'::jsonb NOT NULL,
    parts_cost numeric(14,2) DEFAULT 0 NOT NULL,
    labor_cost numeric(14,2) DEFAULT 0 NOT NULL,
    downtime_minutes integer DEFAULT 0 NOT NULL,
    outcome text,
    completion_notes text,
    next_due_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT work_orders_completed_fields CHECK (((status <> 'completed'::public.work_order_status) OR ((completed_at IS NOT NULL) AND (btrim(COALESCE(outcome, ''::text)) <> ''::text)))),
    CONSTRAINT work_orders_costs_non_negative CHECK (((parts_cost >= (0)::numeric) AND (labor_cost >= (0)::numeric))),
    CONSTRAINT work_orders_downtime_non_negative CHECK ((downtime_minutes >= 0))
);


--
-- Name: COLUMN work_orders.template_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.work_orders.template_id IS 'NULL means a corrective (fault) job; NOT NULL means preventive, generated from a template.';


--
-- Name: fact_asset; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fact_asset AS
 SELECT a.id AS asset_id,
    a.asset_tag,
    a.serial_number,
    a.brand,
    a.model,
    COALESCE(((a.brand || ' '::text) || a.model), a.model, a.brand) AS brand_model,
    (a.condition)::text AS condition,
    (a.status)::text AS status,
    (a.status = 'active'::public.asset_status) AS is_active,
    (a.status = ANY (ARRAY['retired'::public.asset_status, 'disposed'::public.asset_status])) AS is_retired,
    a.category_id,
    c.category_code,
    c.category_name,
    c.category_group_name,
    c.useful_life_months,
    a.current_location_id AS location_id,
    l.location_code,
    l.location_name,
    l.campus,
    l.building,
    l.floor,
    l.room,
    l.location_path,
    l.org_unit_id,
    l.org_unit_name,
    l.college,
    l.department,
    a.custodian_user_id,
    cu.full_name AS custodian_name,
    (a.custodian_user_id IS NOT NULL) AS has_custodian,
    a.purchase_date,
    (date_trunc('month'::text, (a.purchase_date)::timestamp with time zone))::date AS purchase_month,
    (EXTRACT(year FROM a.purchase_date))::integer AS purchase_year,
    a.purchase_cost,
    (CURRENT_DATE - a.purchase_date) AS age_days,
    round((((CURRENT_DATE - a.purchase_date))::numeric / 30.44), 1) AS age_months,
    round((((CURRENT_DATE - a.purchase_date))::numeric / 365.25), 2) AS age_years,
        CASE
            WHEN ((c.useful_life_months IS NULL) OR (c.useful_life_months = 0)) THEN NULL::numeric
            ELSE round(((((CURRENT_DATE - a.purchase_date))::numeric / 30.44) / (c.useful_life_months)::numeric), 3)
        END AS life_consumed_ratio,
        CASE
            WHEN (c.useful_life_months IS NULL) THEN 'no policy'::text
            WHEN (((((CURRENT_DATE - a.purchase_date))::numeric / 30.44) / (c.useful_life_months)::numeric) >= 1.0) THEN 'past useful life'::text
            WHEN (((((CURRENT_DATE - a.purchase_date))::numeric / 30.44) / (c.useful_life_months)::numeric) >= 0.8) THEN 'near end of life'::text
            WHEN (((((CURRENT_DATE - a.purchase_date))::numeric / 30.44) / (c.useful_life_months)::numeric) >= 0.5) THEN 'mid life'::text
            ELSE 'early life'::text
        END AS lifecycle_stage,
    a.next_maintenance_due_at,
    (a.next_maintenance_due_at)::date AS next_due_date,
        CASE
            WHEN (a.next_maintenance_due_at IS NULL) THEN NULL::integer
            ELSE ((a.next_maintenance_due_at)::date - CURRENT_DATE)
        END AS days_to_due,
        CASE
            WHEN (a.next_maintenance_due_at IS NULL) THEN 'not scheduled'::text
            WHEN (a.next_maintenance_due_at < now()) THEN 'overdue'::text
            WHEN (a.next_maintenance_due_at < (now() + '30 days'::interval)) THEN 'due in 30 days'::text
            WHEN (a.next_maintenance_due_at < (now() + '90 days'::interval)) THEN 'due in 90 days'::text
            ELSE 'scheduled'::text
        END AS maintenance_bucket,
    w.warranty_expires_at,
        CASE
            WHEN (w.warranty_expires_at IS NULL) THEN NULL::integer
            ELSE (w.warranty_expires_at - CURRENT_DATE)
        END AS warranty_days_left,
        CASE
            WHEN (w.warranty_expires_at IS NULL) THEN 'no warranty on record'::text
            WHEN (w.warranty_expires_at < CURRENT_DATE) THEN 'expired'::text
            WHEN (w.warranty_expires_at <= (CURRENT_DATE + 30)) THEN 'expiring in 30 days'::text
            WHEN (w.warranty_expires_at <= (CURRENT_DATE + 90)) THEN 'expiring in 90 days'::text
            ELSE 'covered'::text
        END AS warranty_bucket,
    w.warranty_provider,
    inv.supplier_name,
    inv.purchase_order_number,
    inv.invoice_number,
    inv.invoice_amount,
    COALESCE(m.work_order_count, (0)::bigint) AS work_order_count,
    COALESCE(m.preventive_count, (0)::bigint) AS preventive_count,
    COALESCE(m.corrective_count, (0)::bigint) AS corrective_count,
    COALESCE(m.corrective_12m, (0)::bigint) AS corrective_last_12m,
    COALESCE(m.downtime_minutes, (0)::bigint) AS downtime_minutes_total,
    round(((COALESCE(m.downtime_minutes, (0)::bigint))::numeric / 60.0), 1) AS downtime_hours_total,
    COALESCE(m.maintenance_cost, (0)::numeric) AS maintenance_cost_total,
        CASE
            WHEN ((a.purchase_cost IS NULL) OR (a.purchase_cost = (0)::numeric)) THEN NULL::numeric
            ELSE round((COALESCE(m.maintenance_cost, (0)::numeric) / a.purchase_cost), 3)
        END AS maintenance_to_purchase_ratio,
    m.last_service_at,
    (m.last_service_at)::date AS last_service_date,
    a.risk_band,
        CASE a.risk_band
            WHEN 'critical'::text THEN 4
            WHEN 'high'::text THEN 3
            WHEN 'medium'::text THEN 2
            WHEN 'low'::text THEN 1
            ELSE 0
        END AS risk_rank,
    ( SELECT string_agg((x.value ->> 'detail'::text), ' | '::text) AS string_agg
           FROM jsonb_array_elements(a.risk_reasons) x(value)
          WHERE ((x.value ->> 'code'::text) <> 'score'::text)) AS risk_reasons_text,
    ( SELECT ((x.value ->> 'weight'::text))::numeric AS "numeric"
           FROM jsonb_array_elements(a.risk_reasons) x(value)
          WHERE ((x.value ->> 'code'::text) = 'score'::text)
         LIMIT 1) AS risk_score,
    a.retired_at,
    (a.retired_at)::date AS retired_date,
    a.retirement_reason,
    a.created_at,
    (a.created_at)::date AS registered_date
   FROM ((((((public.assets a
     JOIN public.dim_category c ON ((c.category_id = a.category_id)))
     JOIN public.dim_location l ON ((l.location_id = a.current_location_id)))
     LEFT JOIN public.users cu ON ((cu.id = a.custodian_user_id)))
     LEFT JOIN LATERAL ( SELECT d.warranty_expires_at,
            d.warranty_provider
           FROM public.asset_documents d
          WHERE ((d.asset_id = a.id) AND (d.document_type = 'warranty'::public.document_type))
          ORDER BY d.warranty_expires_at DESC NULLS LAST
         LIMIT 1) w ON (true))
     LEFT JOIN LATERAL ( SELECT d.supplier_name,
            d.purchase_order_number,
            d.invoice_number,
            d.invoice_amount
           FROM public.asset_documents d
          WHERE ((d.asset_id = a.id) AND (d.document_type = 'invoice'::public.document_type))
          ORDER BY d.created_at
         LIMIT 1) inv ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS work_order_count,
            count(*) FILTER (WHERE (wo.template_id IS NOT NULL)) AS preventive_count,
            count(*) FILTER (WHERE (wo.template_id IS NULL)) AS corrective_count,
            count(*) FILTER (WHERE ((wo.template_id IS NULL) AND (wo.completed_at > (now() - '1 year'::interval)))) AS corrective_12m,
            COALESCE(sum(wo.downtime_minutes), (0)::bigint) AS downtime_minutes,
            COALESCE(sum((wo.parts_cost + wo.labor_cost)), (0)::numeric) AS maintenance_cost,
            max(wo.completed_at) AS last_service_at
           FROM public.work_orders wo
          WHERE ((wo.asset_id = a.id) AND (wo.status = 'completed'::public.work_order_status))) m ON (true));


--
-- Name: fact_asset_event; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fact_asset_event AS
 SELECT e.id AS event_id,
    e.asset_id,
    a.asset_tag,
    (e.event_type)::text AS event_type,
        CASE
            WHEN (e.event_type = ANY (ARRAY['transfer_requested'::public.event_type, 'transfer_approved'::public.event_type, 'location_changed'::public.event_type, 'custody_changed'::public.event_type])) THEN 'movement'::text
            WHEN (e.event_type = 'maintenance_completed'::public.event_type) THEN 'maintenance'::text
            WHEN (e.event_type = ANY (ARRAY['retirement_requested'::public.event_type, 'retired'::public.event_type, 'disposed'::public.event_type])) THEN 'lifecycle'::text
            WHEN (e.event_type = ANY (ARRAY['created'::public.event_type, 'imported'::public.event_type])) THEN 'registration'::text
            ELSE 'other'::text
        END AS event_group,
    e.occurred_at,
    (e.occurred_at)::date AS event_date,
    (date_trunc('month'::text, e.occurred_at))::date AS event_month,
    e.actor_user_id,
    actor.full_name AS actor_name,
    e.from_location_id,
    fl.location_name AS from_location,
    fl.building AS from_building,
    e.to_location_id,
    tl.location_name AS to_location,
    tl.building AS to_building,
    e.from_custodian_user_id,
    fc.full_name AS from_custodian,
    e.to_custodian_user_id,
    tc.full_name AS to_custodian,
    (e.event_data ->> 'reason'::text) AS reason,
    (e.event_data ->> 'kind'::text) AS maintenance_kind,
    e.event_data
   FROM ((((((public.asset_events e
     JOIN public.assets a ON ((a.id = e.asset_id)))
     LEFT JOIN public.users actor ON ((actor.id = e.actor_user_id)))
     LEFT JOIN public.dim_location fl ON ((fl.location_id = e.from_location_id)))
     LEFT JOIN public.dim_location tl ON ((tl.location_id = e.to_location_id)))
     LEFT JOIN public.users fc ON ((fc.id = e.from_custodian_user_id)))
     LEFT JOIN public.users tc ON ((tc.id = e.to_custodian_user_id)));


--
-- Name: fact_audit_log; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fact_audit_log AS
 SELECT al.id AS audit_id,
    al.actor_user_id,
    u.full_name AS actor_name,
    (u.email)::text AS actor_email,
    al.action,
    split_part(al.action, '.'::text, 1) AS action_domain,
    split_part(al.action, '.'::text, 2) AS action_name,
        CASE
            WHEN (al.action ~~ 'auth.login_failed%'::text) THEN true
            ELSE false
        END AS is_failed_login,
    al.table_name,
    host(al.ip_address) AS ip_address,
    al.user_agent,
        CASE
            WHEN ((al.user_agent ~~* '%Android%'::text) OR (al.user_agent ~~* '%Mobile%'::text)) THEN 'mobile'::text
            ELSE 'desktop'::text
        END AS device_type,
    al.created_at,
    (al.created_at)::date AS event_date,
    (date_trunc('month'::text, al.created_at))::date AS event_month,
    (EXTRACT(hour FROM al.created_at))::integer AS event_hour
   FROM (public.audit_log al
     LEFT JOIN public.users u ON ((u.id = al.actor_user_id)));


--
-- Name: fact_document; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fact_document AS
 SELECT d.id AS document_id,
    d.asset_id,
    a.asset_tag,
    l.org_unit_id,
    l.org_unit_name,
    l.building,
    (d.document_type)::text AS document_type,
    d.supplier_name,
    d.purchase_order_number,
    d.invoice_number,
    d.invoice_amount,
    d.warranty_provider,
    d.warranty_expires_at,
        CASE
            WHEN (d.warranty_expires_at IS NULL) THEN NULL::integer
            ELSE (d.warranty_expires_at - CURRENT_DATE)
        END AS warranty_days_left,
        CASE
            WHEN (d.warranty_expires_at IS NULL) THEN 'not a warranty'::text
            WHEN (d.warranty_expires_at < CURRENT_DATE) THEN 'expired'::text
            WHEN (d.warranty_expires_at <= (CURRENT_DATE + 30)) THEN 'expiring in 30 days'::text
            WHEN (d.warranty_expires_at <= (CURRENT_DATE + 90)) THEN 'expiring in 90 days'::text
            ELSE 'covered'::text
        END AS warranty_bucket,
    d.mime_type,
    d.byte_size,
    round(((d.byte_size)::numeric / 1048576.0), 2) AS size_mb,
    (d.malware_scan_status)::text AS scan_status,
    (d.malware_scan_status = 'clean'::public.malware_scan_status) AS is_downloadable,
    d.uploaded_by,
    u.full_name AS uploaded_by_name,
    d.created_at,
    (d.created_at)::date AS uploaded_date
   FROM (((public.asset_documents d
     JOIN public.assets a ON ((a.id = d.asset_id)))
     JOIN public.dim_location l ON ((l.location_id = a.current_location_id)))
     LEFT JOIN public.users u ON ((u.id = d.uploaded_by)));


--
-- Name: maintenance_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.maintenance_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    category_id uuid NOT NULL,
    name text NOT NULL,
    trigger_type public.trigger_type NOT NULL,
    interval_days integer,
    runtime_hours integer,
    condition_rule jsonb DEFAULT '{}'::jsonb NOT NULL,
    checklist jsonb DEFAULT '[]'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    CONSTRAINT maintenance_templates_name_not_blank CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT maintenance_templates_trigger_config CHECK ((((trigger_type = 'calendar'::public.trigger_type) AND (interval_days IS NOT NULL) AND (interval_days > 0)) OR ((trigger_type = 'runtime'::public.trigger_type) AND (runtime_hours IS NOT NULL) AND (runtime_hours > 0)) OR ((trigger_type = 'condition'::public.trigger_type) AND (condition_rule <> '{}'::jsonb))))
);


--
-- Name: fact_work_order; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.fact_work_order AS
 SELECT wo.id AS work_order_id,
    wo.asset_id,
    a.asset_tag,
    a.category_id,
    c.category_code,
    c.category_name,
    a.current_location_id AS location_id,
    l.building,
    l.floor,
    l.room,
    l.location_name,
    l.org_unit_id,
    l.org_unit_name,
    l.college,
    l.department,
    wo.template_id,
    mt.name AS template_name,
        CASE
            WHEN (wo.template_id IS NOT NULL) THEN 'preventive'::text
            ELSE 'corrective'::text
        END AS work_order_kind,
    wo.technician_user_id,
    t.full_name AS technician_name,
    (wo.priority)::text AS priority,
        CASE wo.priority
            WHEN 'critical'::public.work_order_priority THEN 4
            WHEN 'high'::public.work_order_priority THEN 3
            WHEN 'medium'::public.work_order_priority THEN 2
            ELSE 1
        END AS priority_rank,
    (wo.status)::text AS status,
    (wo.status = 'completed'::public.work_order_status) AS is_completed,
    (wo.status = ANY (ARRAY['open'::public.work_order_status, 'scheduled'::public.work_order_status, 'in_progress'::public.work_order_status])) AS is_outstanding,
    wo.scheduled_at,
    (wo.scheduled_at)::date AS scheduled_date,
    wo.started_at,
    (wo.started_at)::date AS started_date,
    wo.completed_at,
    (wo.completed_at)::date AS completed_date,
    (date_trunc('month'::text, wo.completed_at))::date AS completed_month,
    wo.next_due_at,
    (wo.next_due_at)::date AS next_due_date,
        CASE
            WHEN ((wo.status = ANY (ARRAY['open'::public.work_order_status, 'scheduled'::public.work_order_status, 'in_progress'::public.work_order_status])) AND (wo.scheduled_at < now())) THEN true
            ELSE false
        END AS is_overdue,
        CASE
            WHEN ((wo.status = ANY (ARRAY['open'::public.work_order_status, 'scheduled'::public.work_order_status, 'in_progress'::public.work_order_status])) AND (wo.scheduled_at < now())) THEN (CURRENT_DATE - (wo.scheduled_at)::date)
            ELSE NULL::integer
        END AS days_overdue,
        CASE
            WHEN ((wo.completed_at IS NOT NULL) AND (wo.started_at IS NOT NULL)) THEN round((EXTRACT(epoch FROM (wo.completed_at - wo.started_at)) / 3600.0), 2)
            ELSE NULL::numeric
        END AS repair_hours,
        CASE
            WHEN ((wo.completed_at IS NOT NULL) AND (wo.scheduled_at IS NOT NULL)) THEN round((EXTRACT(epoch FROM (wo.completed_at - wo.scheduled_at)) / 3600.0), 2)
            ELSE NULL::numeric
        END AS response_hours,
    wo.parts_cost,
    wo.labor_cost,
    (wo.parts_cost + wo.labor_cost) AS total_cost,
    wo.downtime_minutes,
    round(((wo.downtime_minutes)::numeric / 60.0), 2) AS downtime_hours,
    wo.outcome,
    wo.completion_notes,
    wo.created_at,
    (wo.created_at)::date AS created_date
   FROM (((((public.work_orders wo
     JOIN public.assets a ON ((a.id = wo.asset_id)))
     JOIN public.dim_category c ON ((c.category_id = a.category_id)))
     JOIN public.dim_location l ON ((l.location_id = a.current_location_id)))
     LEFT JOIN public.maintenance_templates mt ON ((mt.id = wo.template_id)))
     LEFT JOIN public.users t ON ((t.id = wo.technician_user_id)));


--
-- Name: kpi_inventory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kpi_inventory AS
 SELECT org_unit_name,
    college,
    department,
    building,
    category_group_name,
    category_name,
    count(*) AS asset_count,
    count(*) FILTER (WHERE (status = 'active'::text)) AS active_count,
    count(*) FILTER (WHERE is_retired) AS retired_count,
    count(*) FILTER (WHERE (status = 'lost'::text)) AS lost_count,
    count(*) FILTER (WHERE ((NOT has_custodian) AND (status = 'active'::text))) AS without_custodian,
    count(*) FILTER (WHERE (serial_number IS NULL)) AS without_serial,
    round(((100.0 * (count(*) FILTER (WHERE (has_custodian AND (serial_number IS NOT NULL))))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS completeness_pct,
    COALESCE(sum(purchase_cost), (0)::numeric) AS total_purchase_cost,
    round(avg(age_years), 2) AS avg_age_years
   FROM public.fact_asset
  GROUP BY org_unit_name, college, department, building, category_group_name, category_name;


--
-- Name: kpi_maintenance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kpi_maintenance AS
 SELECT org_unit_name,
    building,
    category_name,
    count(*) AS work_order_count,
    count(*) FILTER (WHERE (work_order_kind = 'preventive'::text)) AS preventive_count,
    count(*) FILTER (WHERE (work_order_kind = 'corrective'::text)) AS corrective_count,
    round(((100.0 * (count(*) FILTER (WHERE (work_order_kind = 'preventive'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS preventive_pct,
    count(*) FILTER (WHERE is_outstanding) AS outstanding_count,
    count(*) FILTER (WHERE is_overdue) AS overdue_count,
    round(avg(repair_hours) FILTER (WHERE is_completed), 2) AS mttr_hours,
    COALESCE(sum(downtime_minutes), (0)::bigint) AS downtime_minutes,
    round(((COALESCE(sum(downtime_minutes), (0)::bigint))::numeric / 60.0), 1) AS downtime_hours,
    COALESCE(sum(total_cost), (0)::numeric) AS maintenance_cost
   FROM public.fact_work_order
  GROUP BY org_unit_name, building, category_name;


--
-- Name: kpi_maintenance_monthly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kpi_maintenance_monthly AS
 SELECT completed_month AS month,
    work_order_kind,
    count(*) AS jobs_completed,
    sum(total_cost) AS total_cost,
    round(((sum(downtime_minutes))::numeric / 60.0), 1) AS downtime_hours,
    round(avg(repair_hours), 2) AS avg_repair_hours
   FROM public.fact_work_order
  WHERE (is_completed AND (completed_month IS NOT NULL))
  GROUP BY completed_month, work_order_kind;


--
-- Name: kpi_risk_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kpi_risk_queue AS
 SELECT asset_id,
    asset_tag,
    category_name,
    building,
    room,
    org_unit_name,
    custodian_name,
    condition,
    age_years,
    lifecycle_stage,
    corrective_last_12m,
    downtime_hours_total,
    maintenance_cost_total,
    maintenance_bucket,
    warranty_bucket,
    risk_band,
    risk_rank,
    risk_score,
    risk_reasons_text
   FROM public.fact_asset
  WHERE ((NOT is_retired) AND (risk_band = ANY (ARRAY['medium'::text, 'high'::text, 'critical'::text])));


--
-- Name: kpi_warranty; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.kpi_warranty AS
 SELECT org_unit_name,
    building,
    category_name,
    warranty_bucket,
    count(*) AS asset_count,
    sum(purchase_cost) AS purchase_cost_at_risk
   FROM public.fact_asset
  WHERE (NOT is_retired)
  GROUP BY org_unit_name, building, category_name, warranty_bucket;


